public sealed class OrderService(AppDbContext db)
{
    public async Task<OrderSummaryDto?> GetSummaryAsync(Guid id, CancellationToken ct)
        => await db.Orders.AsNoTracking()
            .Where(o => o.Id == id)
            .Select(o => new OrderSummaryDto(o.Id, o.Total, o.Status))
            .FirstOrDefaultAsync(ct);

    public async Task ShipAsync(Guid id, CancellationToken ct)
    {
        var order = await db.Orders.AsTracking().FirstAsync(o => o.Id == id, ct);
        order.Status = OrderStatus.Shipped;
        await db.SaveChangesAsync(ct);
    }
}

